INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '首句判断', 'kp-xingce-language-sentence-reorder-first-sentence', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "首句判断"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "什么句子绝对不能当第一句？"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、排雷原则"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "有代词的绝对不能当首句（“这”、“那些”）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "有关联词后半截的绝对不能当首句（“但是”、“因此”、“从而”）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "有具体细节的不能当首句，首句通常是宏大的背景介绍、下定义的客观陈述。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、实战用法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "看选项的排头兵。如果 A/B 把 ② 当首句，C/D 把 ④ 当首句。直接对比 ② 和 ④ 谁更配当老大。如果 ② 里面有个“因此”，A 和 B 直接死亡。"}]}]}$$ AS jsonb), NULL, '首句判断的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "语句表达", "首句判断"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_sentence_reorder_first_sentence", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
